@cython.cclass
class bedGraphTrackI:
    """Sparse representation of a bedGraph signal track.

    The implementation assumes regions are continuous and non-overlapping
    within each chromosome. Coordinates are stored as 0-based, right-open
    transition points paired with the preceding value.
    """
    __data: dict
    maxvalue = cython.declare(cython.float, visibility="public")
    minvalue = cython.declare(cython.float, visibility="public")
    baseline_value = cython.declare(cython.float, visibility="public")

    def __init__(self, baseline_value: cython.float = 0):
        """Initialise an empty track with a default baseline value.

        Args:
            baseline_value: Score used to fill uncovered bases when new
                segments are appended.
        """
        self.__data = {}
        self.maxvalue = -10000000  # initial maximum value is tiny since I want safe_add_loc to update it
        self.minvalue = 10000000  # initial minimum value is large since I want safe_add_loc to update it
        self.baseline_value = baseline_value

    @cython.ccall
    def add_loc(self, chromosome: bytes,
                startpos: cython.int,
                endpos: cython.int,
                value: cython.float):
        """Append ``[startpos, endpos)`` with ``value`` on ``chromosome``.

        The caller is responsible for providing non-overlapping, sorted
        regions. Adjacent regions with identical values are merged.
        """
        pre_v: cython.float

        # basic assumption, end pos should > start pos

        if endpos <= 0:
            return
        if startpos < 0:
            startpos = 0

        if chromosome not in self.__data:
            self.__data[chromosome] = [pyarray('i', []),
                                       pyarray('f', [])]
            c = self.__data[chromosome]
            if startpos:
                # start pos is not 0, then add two blocks, the first
                # with "baseline_value"; the second with "value"
                c[0].append(startpos)
                c[1].append(self.baseline_value)
            c[0].append(endpos)
            c[1].append(value)
        else:
            c = self.__data[chromosome]
            # get the preceding region
            pre_v = c[1][-1]

            # if this region is next to the previous one.
            if pre_v == value:
                # if value is the same, simply extend it.
                c[0][-1] = endpos
            else:
                # otherwise, add a new region
                c[0].append(endpos)
                c[1].append(value)

        if value > self.maxvalue:
            self.maxvalue = value
        if value < self.minvalue:
            self.minvalue = value

    @cython.ccall
    def add_loc_wo_merge(self, chromosome: bytes,
                         startpos: cython.int,
                         endpos: cython.int,
                         value: cython.float):
        """Append ``[startpos, endpos)`` without merging identical neighbours."""
        if endpos <= 0:
            return
        if startpos < 0:
            startpos = 0

        if value < self.baseline_value:
            value = self.baseline_value

        if chromosome not in self.__data:
            self.__data[chromosome] = [pyarray('i', []),
                                       pyarray('f', [])]
            c = self.__data[chromosome]
            if startpos:
                # start pos is not 0, then add two blocks, the first
                # with "baseline_value"; the second with "value"
                c[0].append(startpos)
                c[1].append(self.baseline_value)
        c = self.__data[chromosome]
        c[0].append(endpos)
        c[1].append(value)
        if value > self.maxvalue:
            self.maxvalue = value
        if value < self.minvalue:
            self.minvalue = value

    @cython.ccall
    def add_chrom_data(self,
                       chromosome: bytes,
                       p: pyarray,
                       v: pyarray):
        """Replace ``chromosome`` data using position and value arrays."""
        maxv: cython.float
        minv: cython.float

        self.__data[chromosome] = [p, v]
        maxv = max(v)
        minv = min(v)
        if maxv > self.maxvalue:
            self.maxvalue = maxv
        if minv < self.minvalue:
            self.minvalue = minv
        return

    @cython.ccall
    def add_chrom_data_PV(self,
                          chromosome: bytes,
                          pv: cnp.ndarray):
        """Replace ``chromosome`` data from a structured numpy array ``pv``."""
        maxv: cython.float
        minv: cython.float

        self.__data[chromosome] = [pyarray('i', pv['p']),
                                   pyarray('f', pv['v'])]
        minv = pv['v'].min()
        maxv = pv['v'].max()
        if maxv > self.maxvalue:
            self.maxvalue = maxv
        if minv < self.minvalue:
            self.minvalue = minv
        return

    @cython.ccall
    def destroy(self) -> bool:
        """Release stored chromosome data and reset caches."""
        chrs: set
        chrom: bytes

        chrs = self.get_chr_names()
        for chrom in sorted(chrs):
            if chrom in self.__data:
                self.__data[chrom] = [None, None]
                self.__data.pop(chrom)
        return True

    @cython.ccall
    def get_data_by_chr(self, chromosome: bytes) -> list:
        """Return ``(positions, values)`` arrays for ``chromosome``."""
        if chromosome in self.__data:
            return self.__data[chromosome]
        else:
            return []

    @cython.ccall
    def get_chr_names(self) -> set:
        """Return the set of chromosomes currently stored."""
        return set(sorted(self.__data.keys()))

    @cython.ccall
    def reset_baseline(self, baseline_value: cython.float):
        """Reset ``baseline_value`` and clamp regions below the new baseline."""
        self.baseline_value = baseline_value
        self.filter_score(cutoff=baseline_value)
        self.merge_regions()
        return

