def random_track(rng, chrom, maxpos=60):
    """Build a valid piecewise-constant track: contiguous segments from 0."""
    n = rng.randint(1, 6)
    cuts = sorted(rng.sample(range(1, maxpos), n))
    segs = []
    pre = 0
    for c in cuts:
        segs.append((pre, c, float(rng.choice([0.0, 0.5, 1.0, 2.0, 2.0, 3.5, 7.0]))))
        pre = c
    return segs


