    out = []
    for _ in range(n):
        s = rng.randint(0, maxpos - 1)
        e = s + rng.randint(1, 25)
        out.append((s, e))
    return out


def main():
    rng = random.Random(20260814)
    stats = {"orig_ok": 0, "orig_err": 0, "mismatch": 0, "cases": 0}
    mismatches = []
