        if rng.random() < 0.15:
            track[b"cY"] = random_track(rng, b"cY")   # track chrom w/o peaks
        stats["cases"] += 1
        try:
            base = orig(track, peaks, guard=False)
            stats["orig_ok"] += 1
        except IndexError:
            stats["orig_err"] += 1
            base = None
        except Exception as exc:
            print("unexpected orig failure", type(exc).__name__, exc, track, peaks)
            return 1
        guarded = orig(track, peaks, guard=True)
        got = new(track, peaks)
        if base is not None and base != guarded:
            print("guard changed a working case!", track, peaks, base, guarded)
            return 1
