import random
import sys
sys.path.insert(0, "/tmp/h")
from model import orig, new


def structured_track(rng):
    """Include duplicate breakpoints (zero-length segments) and equal values."""
    segs = []
    pre = 0
    for _ in range(rng.randint(1, 7)):
        length = rng.choice([0, 1, 3, 10, 25])
        segs.append((pre, pre + length, float(rng.choice([0.0, 1.0, 1.0, 4.0]))))
        pre = pre + length
    return [s for s in segs] or [(0, 10, 1.0)]


def structured_peaks(rng, track):
    """Nested / adjacent / duplicate / breakpoint-aligned / far-away regions."""
    bounds = sorted({0} | {s[0] for s in track} | {s[1] for s in track})
    out = []
    for _ in range(rng.randint(1, 6)):
        kind = rng.random()
        if kind < 0.35 and len(bounds) > 1:
            a, b = sorted(rng.sample(bounds, 2))
            out.append((a, b))                      # breakpoint aligned
        elif kind < 0.6:
            a = rng.choice(bounds)
            out.append((a + rng.randint(-3, 3), a + rng.randint(-3, 3)))  # misaligned, maybe degenerate
        elif kind < 0.8 and out:
            s, e = out[-1]
            out.append((s, e))                      # exact duplicate
        else:
            a = rng.randint(0, 200)
            out.append((a, a + rng.randint(0, 30)))  # far away / zero length
    return [(max(0, s), max(0, e)) for s, e in out]


def invariants(track, peaks, res):
    segs = {c: t for c, t in track.items()}
    for chrom in {r[0] for r in res}:
        rows = [r for r in res if r[0] == chrom]
        for (_, s, e, score, summit) in rows:
            assert s < e, ("empty interval", rows)
            assert s <= summit < e, ("summit outside", rows)
            covering = [v for (a, b, v) in segs[chrom] if a < e and b > s]
            assert score in covering, ("score not a track value", score, covering)
            assert any(ps <= s and e <= pe for (ps, pe) in peaks[chrom]), ("not inside a candidate", rows)
        rows.sort(key=lambda r: r[1])
        for prev, cur in zip(rows, rows[1:]):
            assert prev[2] <= cur[1], ("outputs overlap -> re-used evidence", rows)
        assert len(rows) <= len(peaks[chrom])


def main():
    rng = random.Random(7)
    err = {"orig": 0}
    for _ in range(40000):
        track = {b"c1": structured_track(rng)}
        peaks = {b"c1": structured_peaks(rng, track[b"c1"])}
        if rng.random() < 0.2:
            peaks[b"c1"] = []
        try:
            orig(track, peaks, guard=False)
        except Exception:
            err["orig"] += 1
        got = new(track, peaks)          # must never raise
        valid_track = all(a < b for (a, b, _) in track[b"c1"])
        valid_peaks = all(s < e for (s, e) in peaks[b"c1"])
        if valid_track and valid_peaks and peaks[b"c1"]:
            invariants(track, peaks, got)
        guarded = orig(track, peaks, guard=True)
        if valid_track and valid_peaks and guarded != got:
            print("MISMATCH on valid input", track, peaks, guarded, got)
            return 2
    print("ok; original raised on", err["orig"], "of 40000 structured cases")
    return 0


raise SystemExit(main())
